DELIMITER $$
CREATE TRIGGER `trg_trainee_school_id_format` BEFORE INSERT ON `tbl_trainee_hdr` FOR EACH ROW BEGIN
    IF NEW.trainee_school_id IS NOT NULL AND NEW.trainee_school_id NOT REGEXP '^[A-Z]{2}-[0-9]{4}-[0-9]{4}$' THEN
